#Requires -Version 5.1
# GOAT Tweaks 7.3.0-preview. Original application built from the supplied specification.
# Self-contained, offline resources. No network bootstrap and no automatic tweaks.
[CmdletBinding()]
param([switch]$Demo,[switch]$ScanOnly,[string]$DataRoot,[string]$SessionPath)
$script:GoatLaunchPath=$PSCommandPath
function Read-GoatPackedResource([string]$Value){
    $memory=[IO.MemoryStream]::new([Convert]::FromBase64String($Value))
    $gzip=[IO.Compression.GZipStream]::new($memory,[IO.Compression.CompressionMode]::Decompress)
    $reader=[IO.StreamReader]::new($gzip,[Text.Encoding]::UTF8)
    try{$reader.ReadToEnd()}finally{$reader.Dispose();$gzip.Dispose();$memory.Dispose()}
}
$script:GoatSources=@{}

$script:GoatSources['Core']=Read-GoatPackedResource ''

$script:GoatSources['Gpu']=Read-GoatPackedResource ''

$script:GoatSources['Inventory']=Read-GoatPackedResource ''

$script:GoatSources['Benchmark']=Read-GoatPackedResource ''

$script:GoatSources['Reports']=Read-GoatPackedResource ''

$script:GoatSources['Presentation']=Read-GoatPackedResource ''

$script:GoatSources['App']=Read-GoatPackedResource ''

$script:GoatXaml=Read-GoatPackedResource ''

$script:GoatCatalogJson=Read-GoatPackedResource ''

$script:GoatDocumentsJson=Read-GoatPackedResource ''

. ([scriptblock]::Create((Read-GoatPackedResource '')))